def check_pc1(tgraph):
    node = tgraph.node("FIREWALL") or {}
    image = node.get("image") or {}
    expected = ["opnsense", "pfsense"]
    if image.get("id") not in expected:
        return {
            "message": "FIREWALL must use an image with firewall appliance capability.",
            "severity": "error",
            "location": "nodes.FIREWALL.image",
            "details": {
                "issue_kind": "physical.image.capability.unsatisfied",
                "constraint_id": "pc1",
                "repair_target": "node.FIREWALL.image",
                "expected_image_ids": expected,
                "actual_image_id": image.get("id"),
            },
        }
    return []


def check_pc2(tgraph):
    node = tgraph.node("INTERNET") or {}
    image = node.get("image") or {}
    expected = ["linux_internet_gateway"]
    if image.get("id") not in expected:
        return {
            "message": "INTERNET must use an image with internet gateway capability.",
            "severity": "error",
            "location": "nodes.INTERNET.image",
            "details": {
                "issue_kind": "physical.image.capability.unsatisfied",
                "constraint_id": "pc2",
                "repair_target": "node.INTERNET.image",
                "expected_image_ids": expected,
                "actual_image_id": image.get("id"),
            },
        }
    return []

