    return tgraph.check_subnet("SW_BRANCH", "10.20.20.0/24")


def check_lc6(tgraph):
    """SW_CORE_FW represents subnet 10.0.0.0/30."""
    return tgraph.check_subnet("SW_CORE_FW", "10.0.0.0/30")


def check_lc7(tgraph):
    """SW_FW_INET represents subnet 10.0.0.4/30."""
    return tgraph.check_subnet("SW_FW_INET", "10.0.0.4/30")


def check_lc8(tgraph):
    """SW_CORE_BRANCH represents subnet 10.0.0.8/30."""
    return tgraph.check_subnet("SW_CORE_BRANCH", "10.0.0.8/30")


def _check_chain(tgraph, chain):
    """Verify that each consecutive pair in the chain are neighbors."""
    issues = []
    for i in range(len(chain) - 1):
        src, dst = chain[i], chain[i + 1]
        neighbors = tgraph.neighbors(node_id=src)
        if dst not in neighbors:
            issues.append({
                "kind": "logical.topology.chain",
                "detail": f"Expected link {src} -> {dst} but {dst} is not a neighbor of {src}",
                "nodes": [src, dst],
                "details": {"repair_target": "graph"},
            })
    return issues if issues else None


def check_lc9(tgraph):
    """Explicit chain WEB -> SW_DMZ -> R_CORE."""
    return _check_chain(tgraph, ["WEB", "SW_DMZ", "R_CORE"])


def check_lc10(tgraph):
    """Explicit chain PC1 -> SW_OFFICE -> R_CORE."""
    return _check_chain(tgraph, ["PC1", "SW_OFFICE", "R_CORE"])


def check_lc11(tgraph):
    """Explicit chain PC2 -> SW_OFFICE -> R_CORE."""
    return _check_chain(tgraph, ["PC2", "SW_OFFICE", "R_CORE"])


def check_lc12(tgraph):
    """Explicit chain PLC1 -> SW_OT -> R_CORE."""
    return _check_chain(tgraph, ["PLC1", "SW_OT", "R_CORE"])


def check_lc13(tgraph):
    """Explicit chain ADMIN -> SW_MGMT -> R_CORE."""
    return _check_chain(tgraph, ["ADMIN", "SW_MGMT", "R_CORE"])


def check_lc14(tgraph):
    """Explicit chain R_CORE -> SW_CORE_FW -> FIREWALL."""
    return _check_chain(tgraph, ["R_CORE", "SW_CORE_FW", "FIREWALL"])


def check_lc15(tgraph):
    """Explicit chain FIREWALL -> SW_FW_INET -> INTERNET."""
    return _check_chain(tgraph, ["FIREWALL", "SW_FW_INET", "INTERNET"])


def check_lc16(tgraph):
    """Explicit chain R_CORE -> SW_CORE_BRANCH -> R_BRANCH -> SW_BRANCH -> BPC1."""
    return _check_chain(tgraph, ["R_CORE", "SW_CORE_BRANCH", "R_BRANCH", "SW_BRANCH", "BPC1"])


def check_lc17(tgraph):
    """All router ports, FIREWALL, and INTERNET interfaces must use fixed IPv4 addresses."""
    issues = []
    nodes_to_check = ["R_CORE", "R_BRANCH", "FIREWALL", "INTERNET"]
    for node_id in nodes_to_check:
        ports = tgraph.ports(node_id=node_id)
        for port in ports:
            ip_addr = port.get("ip")
            if not ip_addr:
                issues.append({
                    "kind": "logical.custom",
                    "detail": f"Port {port.get('port_id', 'unknown')} on {node_id} is missing a fixed IPv4 address",
                    "nodes": [node_id],
                    "details": {"repair_target": "graph"},
                })
    return issues if issues else None

